"use client";
import {
  PremiumUpgradeDialog,
  type PremiumPrice,
} from "@/components/premium-upgrade-dialog";
import { useSendingStatus } from "@/components/sending-status";
import { UpgradePrompt } from "@/components/upgrade-prompt";
import { useRoleSuggestions } from "@/components/role-allowance";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";
import { PremiumLock } from "@/components/premium-lock";
import styles from "./compose.module.css";
import { cn } from "@/lib/utils";
import {
  useWorkspaceEntitlements,
  refreshWorkspaceAccess,
} from "@/components/workspace-quota";
import { SEND_TIMING_DESCRIPTION } from "@/lib/email-limits";
import {
  useEffect,
  useRef,
  useState,
  useTransition,
  type ReactNode,
} from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { Send, Paperclip, ArrowRight, FileText, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { templateSchema } from "@/lib/validation";
import {
  PreviewHighlightPicker,
  usePreviewHighlight,
} from "./preview-highlight";
import {
  FormattedMessage,
  Highlighted,
  previewParts,
} from "@/components/template-preview";
import { submitCampaign, removeFromShortlist } from "@/lib/actions";
import { Feedback, useUnsavedChanges } from "@/components/forms";
import { ProgressRing, estimateSeconds } from "@/components/progress-ring";
import { DateTime } from "@/components/date-time";
import { RoleChoices } from "@/components/preferences";
import { SendChecklist } from "@/components/send-checklist";
import { useWorkspaceQuota } from "@/components/workspace-quota";
import type { QuotaSnapshot } from "@/lib/quota-snapshot";
import { WorkspaceCapacity } from "@/components/workspace-quota";
import type { ActionResult } from "@/lib/errors";
export type ComposeContact = {
  id: string;
  name: string;
  email: string;
  company: string | null;
  jobRole: string | null;
  lastSent: string | null;
  previouslySent: boolean;
  blocked: boolean;
  followUp?: boolean;
};
export function Compose({
  templates,
  contacts,
  recipientSearch,
  recipientSearchQuery = "",
  quota,
  resume,
  connected,
  roles,
  nextSendAt = null,
  observedAt = 0,
  premiumPrice,
}: {
  premiumPrice?: PremiumPrice;
  templates: {
    id: string;
    name: string;
    subject: string;
    body: string;
    eligible?: boolean;
  }[];
  contacts: ComposeContact[];
  recipientSearch?: ReactNode;
  recipientSearchQuery?: string;
  quota: QuotaSnapshot;
  resume: string | null;
  connected: boolean;
  roles: string[];
  nextSendAt?: string | null;
  observedAt?: number;
}) {
  const sendingStatus = useSendingStatus();
  const setSubmitting = sendingStatus?.setSubmitting;
  const access = useWorkspaceEntitlements();
  const upgrade = usePremiumUpgrade();
  const cap = access.limits.campaignRecipients;
  const canUpgradeRecipients =
    access.paidGatingEnabled && access.effectivePlan === "FREE";
  const [recipientUpgradeOpen, setRecipientUpgradeOpen] = useState(false);
  const recipientUpgradeTrigger = useRef<HTMLInputElement>(null);
  const roleChoices = roles;
  const displayedQuota = useWorkspaceQuota(quota);
  const [estimateNow, setEstimateNow] = useState(observedAt);
  useEffect(() => {
    if (!nextSendAt) return;
    const tick = () => setEstimateNow(Date.now());
    tick();
    const timer = setInterval(tick, 1000);
    return () => clearInterval(timer);
  }, [nextSendAt]);
  const [templateId, setTemplateId] = useState("");
  const [selected, setSelected] = useState<ComposeContact[]>([]);
  const [roleFilter, setRoleFilter] = useState("");
  const [recipientRoles, setRecipientRoles] = useState<Record<string, string>>(
    {},
  );
  const [attachResume, setAttachResume] = useState(false);
  const getRole = (c: ComposeContact) =>
    (access.features.recipientRoleOverride
      ? recipientRoles[c.id]
      : undefined) ??
    c.jobRole ??
    "";

  const resendIds = selected
    .filter((c) => c.previouslySent && !c.blocked)
    .map((c) => c.id);
  const highlight = usePreviewHighlight();
  const [previewId, setPreviewId] = useState("");
  const [result, setResult] = useState<ActionResult>();
  const sendButton = useRef<HTMLButtonElement>(null);
  const [exceededAllowances, setExceededAllowances] = useState<
    { label: string; remaining?: number; resetAt?: string | null }[] | null
  >(null);
  const [pending, start] = useTransition();
  useEffect(() => {
    setSubmitting?.(pending);
    return () => setSubmitting?.(false);
  }, [pending, setSubmitting]);
  const [removingId, setRemovingId] = useState("");
  const [removalContact, setRemovalContact] = useState<ComposeContact>();
  const removalDialog = useRef<HTMLDialogElement>(null);
  const removalTrigger = useRef<HTMLButtonElement>(null);
  const shortlistSection = useRef<HTMLElement>(null);
  const removalInFlight = useRef(false);
  const removalSucceeded = useRef(false);
  const [removalResult, setRemovalResult] = useState<ActionResult>();
  const [removing, startRemoval] = useTransition();
  const [idempotencyKey, setKey] = useState("");
  const router = useRouter();
  const roleInput = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (!pending && result?.fieldErrors?.role) roleInput.current?.focus();
  }, [result, pending]);
  const template = templates.find((t) => t.id === templateId);
  const templateValidation = template
    ? templateSchema.safeParse(template)
    : null;
  const preview = selected.find((c) => c.id === previewId) ?? selected[0];
  const included = selected.filter((c) => !c.blocked);
  const missingRoles = included.filter((contact) => !getRole(contact).trim());
  const { list, suggestions } = useRoleSuggestions(roles);
  const readyToSend =
    !!template &&
    (access.limits.savedTemplates === null || template.eligible !== false) &&
    included.length > 0 &&
    selected.length <= cap &&
    missingRoles.length === 0 &&
    (access.features.manualRepeatSend || resendIds.length === 0);
  const busy = pending || removing;
  const filteredContacts = contacts.filter(
    (c) => !roleFilter || getRole(c) === roleFilter,
  );
  const bulkEligible = filteredContacts.filter(
    (c) => !c.blocked && !c.previouslySent,
  );
  const selectedIds = new Set(selected.map((c) => c.id));
  const hasFilteredSelection = bulkEligible.some((c) => selectedIds.has(c.id));
  const allSelected =
    bulkEligible.length > 0 &&
    (bulkEligible.every((c) => selectedIds.has(c.id)) ||
      (selected.length >= cap && hasFilteredSelection));
  useUnsavedChanges(selected.length > 0 && !result?.ok, true);
  function updateRole(id: string, value: string) {
    if (!access.features.recipientRoleOverride) return;
    setRecipientRoles((current) => ({ ...current, [id]: value }));
    setResult(undefined);
    setKey("");
  }
  function toggle(contact: ComposeContact, trigger: HTMLInputElement) {
    if (
      contact.previouslySent &&
      !access.features.manualRepeatSend &&
      !selected.some((c) => c.id === contact.id)
    ) {
      upgrade({ feature: "repeat", trigger });
      return;
    }
    if (!selected.some((c) => c.id === contact.id) && selected.length >= cap) {
      if (canUpgradeRecipients) {
        recipientUpgradeTrigger.current = trigger;
        setRecipientUpgradeOpen(true);
      }
      return;
    }
    setResult(undefined);
    if (selected.some((c) => c.id === contact.id)) {
      setSelected(selected.filter((c) => c.id !== contact.id));
    } else if (selected.length < cap) setSelected([...selected, contact]);
    setKey("");
  }
  function confirmRemoval() {
    if (!removalContact || busy || removalInFlight.current) return;
    const c = removalContact;
    removalInFlight.current = true;
    setRemovingId(c.id);
    setRemovalResult(undefined);
    startRemoval(async () => {
      try {
        const response = await removeFromShortlist(c.id);
        setRemovalResult(response);
        if (response.ok) {
          setSelected((current) =>
            current.filter((person) => person.id !== c.id),
          );
          setRecipientRoles((current) => {
            const next = { ...current };
            delete next[c.id];
            return next;
          });
          setPreviewId((current) => (current === c.id ? "" : current));
          setResult(undefined);
          setKey("");
          removalSucceeded.current = true;
          removalDialog.current?.close();
          router.refresh();
        }
      } catch {
        setRemovalResult({
          ok: false,
          message: "Could not remove this person. Try again.",
        });
      } finally {
        setRemovingId("");
        removalInFlight.current = false;
      }
    });
  }
  return (
    <div className="compose-grid grid grid-cols-[minmax(0,_1.25fr)_minmax(0,_1fr)] gap-4.5 items-start [@media(max-width:_860px)]:grid-cols-[minmax(0,_1fr)]">
      {recipientUpgradeOpen && (
        <PremiumUpgradeDialog
          reason="recipient-limit"
          premiumPrice={premiumPrice}
          returnFocusRef={recipientUpgradeTrigger}
          onClose={() => setRecipientUpgradeOpen(false)}
        />
      )}
      <div className="space-y-[18px]">
        <section className="panel space-y-4 p-5">
          <p className="eyebrow">01 / The message</p>
          <div>
            <label
              htmlFor="compose-template"
              className="mb-2 block text-sm font-medium"
            >
              Choose a template
            </label>
            <select
              id="compose-template"
              disabled={busy}
              name="templateId"
              className="w-full text-sm"
              value={templateId}
              onChange={(e) => {
                const next = templates.find(
                  (candidate) => candidate.id === e.target.value,
                );
                if (
                  access.limits.savedTemplates !== null &&
                  next?.eligible === false
                ) {
                  upgrade({ feature: "templates", trigger: e.currentTarget });
                  return;
                }
                setTemplateId(e.target.value);
                setResult(undefined);
                setKey("");
              }}
            >
              <option value="">Select a template</option>
              {templates.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.name}
                  {access.limits.savedTemplates !== null && t.eligible === false
                    ? " · select in Templates or upgrade"
                    : ""}
                </option>
              ))}
            </select>
            <Link
              href="/templates"
              className="mt-2 inline-flex min-h-11 items-center text-xs text-link"
            >
              Manage Templates{" "}
              <ArrowRight className="ml-1 size-3" aria-hidden="true" />
            </Link>
          </div>
          <div>
            {access.features.recipientRoleOverride ? (
              <>
                <label
                  htmlFor="compose-role"
                  className="mb-2 block text-sm font-medium"
                >
                  Role for {preview?.name ?? "current recipient"}
                </label>
                <Input
                  id="compose-role"
                  ref={roleInput}
                  list={list}
                  disabled={busy || !preview}
                  aria-invalid={!!result?.fieldErrors?.role}
                  aria-describedby={
                    result?.fieldErrors?.role ? "compose-role-error" : undefined
                  }
                  name="role"
                  value={preview ? getRole(preview) : ""}
                  onChange={(e) => {
                    if (preview) updateRole(preview.id, e.target.value);
                    setResult(undefined);
                    setKey("");
                  }}
                  placeholder="Frontend engineer…"
                  maxLength={160}
                  autoComplete="off"
                />
                {suggestions}
                <p className="mt-2 mb-3 text-xs text-body">
                  Edit this recipient’s role for this batch. The preview updates
                  automatically; the saved contact stays unchanged.
                </p>
                <RoleChoices
                  roles={roleChoices}
                  disabled={busy || !preview}
                  onChoose={(r) => {
                    if (preview) updateRole(preview.id, r);
                  }}
                />
              </>
            ) : (
              <>
                <label
                  id="compose-role-label"
                  htmlFor="compose-role"
                  className="mb-2 block text-sm font-medium"
                >
                  Role for {preview?.name ?? "current recipient"}
                </label>
                <div
                  role="group"
                  aria-labelledby="compose-role-label"
                  className="space-y-3"
                >
                  <button
                    id="compose-role"
                    type="button"
                    disabled={
                      busy ||
                      !preview ||
                      access.reasons.recipientRoleOverride !==
                        "UPGRADE_REQUIRED"
                    }
                    className="min-h-11 w-full cursor-pointer rounded-sm border border-control-border bg-surface px-3 py-2 text-left text-sm"
                    aria-describedby="compose-role-guidance"
                    aria-label="Recipient role · Premium required"
                    onClick={(event) =>
                      upgrade({
                        feature: "roles",
                        trigger: event.currentTarget,
                      })
                    }
                  >
                    {preview?.jobRole ||
                      (preview
                        ? "No saved role"
                        : "Select a recipient to view their role")}
                  </button>
                  <div>
                    <div id="compose-role-guidance">
                      <PremiumLock
                        upgradeFeature="roles"
                        feature="Role editing"
                        variant="notice"
                        description="Uses the saved role from Contacts. Edit it in Contacts, or use Premium to change it for this batch."
                      />
                    </div>
                    <Link
                      href="/contacts"
                      className="mt-1 inline-flex min-h-11 items-center gap-1 text-xs font-medium text-link underline underline-offset-4 hover:no-underline"
                    >
                      Edit in Contacts
                      <ArrowRight
                        className="size-3 shrink-0"
                        aria-hidden="true"
                      />
                    </Link>
                  </div>
                </div>
              </>
            )}
            {result?.fieldErrors?.role && (
              <p
                id="compose-role-error"
                className="mt-2 text-xs text-error-deep"
                role="alert"
              >
                {result.fieldErrors.role}
              </p>
            )}
          </div>
        </section>
        <section
          className="panel recipient-panel p-5"
          ref={shortlistSection}
          tabIndex={-1}
          aria-label="Your shortlist"
        >
          <div className="mb-4 flex flex-wrap items-center justify-between gap-2">
            <p className="eyebrow">02 / Your shortlist</p>
            <p aria-live="polite" className="text-xs tabular-nums text-body">
              {selected.length} / {cap} selected
            </p>
          </div>
          <p className="mb-4 text-xs leading-5 text-body">
            Unsent contacts appear here.{" "}
            {access.features.historyShortlist
              ? "Use + in History to add someone to your shortlist and email them again."
              : "To email someone again, enter and save their details in Contacts to add them back to your shortlist."}{" "}
            Select a yellow recipient to authorize a follow-up. Pending
            deliveries remain blocked.
          </p>
          {access.paidGatingEnabled &&
            access.effectivePlan === "FREE" &&
            selected.length >= cap && (
              <UpgradePrompt>
                Your campaign limit is {cap} recipients.
              </UpgradePrompt>
            )}
          {selected.length > cap && (
            <p role="alert">
              Your selection exceeds the current {cap}-recipient limit. Remove
              recipients to continue; your selection has been kept.
            </p>
          )}
          {recipientSearch}
          <label className="mb-4 block text-sm">
            Filter by Job Role
            <select
              aria-label="Filter by Job Role"
              name="roleFilter"
              className="mt-2 w-full"
              value={roleFilter}
              onChange={(e) => setRoleFilter(e.target.value)}
            >
              <option value="">All Roles</option>
              {[...new Set([...roles, ...contacts.map(getRole)])]
                .filter(Boolean)
                .map((r) => (
                  <option key={r}>{r}</option>
                ))}
            </select>
          </label>
          <div className="mb-4 flex flex-wrap items-center gap-3">
            <Button
              variant="outline"
              disabled={
                busy ||
                !bulkEligible.length ||
                (!allSelected && selected.length >= cap)
              }
              onClick={() => {
                if (allSelected) {
                  const filteredIds = new Set(
                    filteredContacts.map((c) => c.id),
                  );
                  setSelected(selected.filter((c) => !filteredIds.has(c.id)));
                } else {
                  setSelected([
                    ...selected,
                    ...bulkEligible
                      .filter((c) => !selectedIds.has(c.id))
                      .slice(0, Math.max(0, cap - selected.length)),
                  ]);
                }
                setResult(undefined);
                setKey("");
              }}
            >
              {allSelected ? "Clear selection" : "Select all"}
            </Button>
            <span className="text-xs text-body">
              Up to {cap} eligible contacts in this filter
            </span>
          </div>
          <div className="space-y-4">
            {!filteredContacts.length && (
              <p className="py-6 text-sm text-body">
                No matching contacts.{" "}
                <Link href="/contacts" className="text-link">
                  Add contacts
                </Link>{" "}
                or change your search.
              </p>
            )}
            {[false, true].map((blocked) => (
              <div key={String(blocked)} className="space-y-4">
                {blocked && filteredContacts.some((c) => c.blocked) && (
                  <h2 className="text-sm font-semibold">Pending delivery</h2>
                )}
                {filteredContacts
                  .filter((c) => c.blocked === blocked)
                  .map((c) => {
                    const checked = selected.some((s) => s.id === c.id);
                    return (
                      <div
                        key={c.id}
                        className={cn(
                          "recipient-card grid gap-3 min-w-0 py-4.5 px-5 border border-solid border-[var(--recipients-border)] rounded-[14px] [background:var(--recipients-card)] text-[var(--recipients-text)] relative",
                          c.previouslySent &&
                            "recipient-card-emailed border-[var(--recipients-pill-border)] [background:var(--recipients-pill-bg)]",
                        )}
                      >
                        {recipientSearchQuery.trim() && (
                          <span
                            key={`${recipientSearchQuery}:${observedAt}`}
                            aria-hidden="true"
                            className={`${styles.searchResultHighlight} absolute inset-0 pointer-events-none rounded-[inherit] [outline:2px_solid_var(--ring)] [outline-offset:-2px] [background:color-mix(in_srgb,_var(--ring)_10%,_transparent)]`}
                          />
                        )}
                        <div className="flex items-center gap-2">
                          <label
                            className={`flex-1 recipient-header recipient-summary min-h-11 ${c.blocked ? "opacity-60" : "cursor-pointer"}`}
                          >
                            <input
                              type="checkbox"
                              checked={checked}
                              aria-label={
                                c.previouslySent &&
                                !access.features.manualRepeatSend
                                  ? `${c.name}: Repeat sending is currently unavailable`
                                  : undefined
                              }
                              onChange={(event) =>
                                toggle(c, event.currentTarget)
                              }
                              disabled={
                                busy ||
                                c.blocked ||
                                (!checked &&
                                  selected.length >= cap &&
                                  !canUpgradeRecipients)
                              }
                            />
                            <span className="min-w-0 flex-1">
                              <span className="block break-words text-[17px] font-semibold">
                                {c.name}{" "}
                                {c.company?.trim() && (
                                  <span className="recipient-company text-[var(--recipients-text-muted)] font-normal">
                                    · {c.company}
                                  </span>
                                )}
                              </span>
                              <span className="recipient-email">{c.email}</span>
                            </span>
                            <span className="recipient-role-badge">
                              {getRole(c).trim() || "No role"}
                            </span>
                          </label>
                          <Button
                            type="button"
                            variant="ghost"
                            size="icon"
                            aria-label={`Remove ${c.name} from shortlist`}
                            title={
                              c.blocked
                                ? "Wait for pending delivery to resolve"
                                : "Remove from shortlist"
                            }
                            disabled={busy || c.blocked}
                            onClick={(event) => {
                              removalTrigger.current = event.currentTarget;
                              removalSucceeded.current = false;
                              setRemovalContact(c);
                              setRemovalResult(undefined);
                              removalDialog.current?.showModal();
                            }}
                          >
                            <X
                              aria-hidden="true"
                              className={
                                removingId === c.id ? "opacity-50" : undefined
                              }
                            />
                          </Button>
                        </div>
                        {c.lastSent && (
                          <dl className="recipient-details grid grid-cols-[72px_minmax(0,_1fr)] gap-x-3 gap-y-2 ml-7.5 text-[13px]">
                            <dt>Last sent</dt>
                            <dd>
                              <DateTime value={c.lastSent} />
                            </dd>
                          </dl>
                        )}
                        {c.blocked && (
                          <p className="recipient-blocked justify-self-start ml-7.5 wrap-anywhere text-[var(--recipients-pill-text)] text-xs">
                            Already queued or awaiting delivery confirmation
                          </p>
                        )}
                        {c.previouslySent && (
                          <p className="status-pill inline-flex items-center gap-1.5 rounded-full py-1 px-[11px] text-[12px] font-semibold recipient-warning justify-self-start ml-7.5 wrap-anywhere text-[var(--recipients-pill-text)] [border:1px_solid_var(--recipients-pill-border)] [background:var(--recipients-pill-bg)]">
                            You already emailed this address
                            {c.lastSent ? (
                              <>
                                {" "}
                                on <DateTime value={c.lastSent} />
                              </>
                            ) : (
                              "."
                            )}
                          </p>
                        )}
                      </div>
                    );
                  })}
              </div>
            ))}
          </div>
          {selected.some((c) => !contacts.some((v) => v.id === c.id)) && (
            <p className="mt-4 text-xs text-body">
              Your selection includes contacts from other search results.
            </p>
          )}
        </section>
      </div>
      <aside className="space-y-4 lg:sticky lg:top-6">
        <section className="panel p-5">
          <div className="mb-3">
            <p className="section-label [font:600_11px/1.5_ui-monospace,_monospace] tracking-[0.14em] uppercase text-body mb-4">
              03 / Personal preview
            </p>
            <label
              htmlFor="preview-recipient"
              className="mb-2 block text-sm font-medium"
            >
              Preview recipient
            </label>
            <div className="preview-recipient-controls flex items-center gap-2">
              <select
                id="preview-recipient"
                className="w-full text-sm flex-1 min-w-0"
                value={preview?.id ?? ""}
                onChange={(e) => setPreviewId(e.target.value)}
              >
                <option value="" disabled>
                  Select a recipient to preview
                </option>
                {selected.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name} · {c.email}
                  </option>
                ))}
              </select>
              <PreviewHighlightPicker />
            </div>
          </div>
          {template && preview ? (
            <div
              data-preview-highlight={highlight}
              className={`mail-preview min-w-0 [background:var(--surface)] [border:1px_solid_var(--border)] rounded-[16px] wrap-anywhere space-y-4 p-4 text-sm leading-6 ${styles.personalPreview}`}
            >
              <p className="break-all text-body">To: {preview.email}</p>
              <h2 className="break-words border-b border-dotted border-separator pb-4 font-medium">
                <Highlighted
                  parts={
                    previewParts(template.subject, {
                      name: preview.name,
                      company: preview.company,
                      role: getRole(preview),
                    }).parts
                  }
                />
              </h2>
              <div
                className="mail-preview-body max-h-[min(440px,_55dvh)] overflow-y-auto whitespace-pre-wrap wrap-anywhere focus-visible:[outline:2px_solid_var(--accent)] focus-visible:[outline-offset:-2px] min-h-40"
                role="region"
                aria-label="Personal message preview"
                tabIndex={0}
              >
                <div className="mail-message-content w-full max-w-160 [font-family:Arial,_Helvetica,_sans-serif] text-[14px] leading-normal text-left">
                  <FormattedMessage
                    parts={
                      previewParts(template.body, {
                        name: preview.name,
                        company: preview.company,
                        role: getRole(preview),
                      }).parts
                    }
                  />
                </div>
              </div>
              {templateValidation?.success === false && (
                <p role="alert" className="text-xs text-error-deep">
                  {templateValidation.error.issues
                    .map((issue) => issue.message)
                    .join(" ")}
                </p>
              )}
              {preview.previouslySent && (
                <p className="text-xs text-warning">
                  You’ve already emailed this address. Selecting this recipient
                  authorizes a follow-up.
                </p>
              )}
            </div>
          ) : (
            <p className="p-6 text-sm leading-6 text-body">
              Choose a template and select a recipient to see their individual
              email.
            </p>
          )}
          <div className="mt-4 space-y-3 border-t border-dotted border-separator pt-3">
            <label className="flex min-h-11 items-center gap-3 text-sm">
              <input
                type="checkbox"
                name="attachResume"
                checked={attachResume}
                disabled={busy || !resume}
                onChange={(e) => {
                  setAttachResume(e.target.checked);
                  setKey("");
                }}
              />
              Attach PDF{!resume && " (upload a PDF in Settings)"}
            </label>
            <p className="flex min-w-0 items-center gap-2 text-xs text-body">
              <FileText className="size-4 shrink-0" aria-hidden="true" />
              <span className="min-w-0 truncate" title={resume ?? undefined}>
                {resume ?? "No PDF uploaded"}
              </span>
            </p>
            <p className="text-xs leading-5 text-body">
              Upload a PDF in Settings, then select “Attach PDF” here.
              Mentioning a PDF in the message does not attach it.
            </p>
          </div>
          <div className="pt-3">
            <p className="flex items-center gap-2 break-all text-xs text-body">
              <Paperclip className="size-4 shrink-0" aria-hidden="true" />
              <span
                className="min-w-0 truncate"
                title={attachResume ? (resume ?? undefined) : undefined}
              >
                {attachResume ? resume : "No PDF attachment"}
              </span>
              <Link href="/settings" className="ml-auto text-link">
                Settings
              </Link>
            </p>
          </div>
        </section>
        <section className="panel send-queue-panel space-y-4 p-5">
          <h2 className="section-label [font:600_11px/1.5_ui-monospace,_monospace] tracking-[0.14em] uppercase text-body">
            Send queue
          </h2>
          <ProgressRing
            sent={0}
            queued={included.length}
            failed={0}
            seconds={estimateSeconds(included.length, nextSendAt, estimateNow)}
            draft
          />
          <p className="text-xs text-body">
            Approximate time for selected recipients, including processing.{" "}
            {SEND_TIMING_DESCRIPTION} Service delays can extend this estimate.
          </p>
          <div className="space-y-2">
            <div className="flex items-center justify-between gap-3 text-sm">
              <span className="text-body">Selected recipients</span>
              <span className="font-medium tabular-nums">
                {included.length} / {cap}
              </span>
            </div>
            <div
              role="progressbar"
              aria-label="Selected recipients"
              aria-valuemin={0}
              aria-valuemax={cap}
              aria-valuenow={Math.min(included.length, cap)}
              aria-valuetext={`${included.length} / ${cap}`}
              className="recipient-meter-track [background:var(--recipients-track)] h-2 overflow-hidden rounded-full"
            >
              <div
                className="queue-meter [background:var(--accent-gradient)] recipient-meter-fill [background:linear-gradient(_135deg,_var(--recipients-accent),_var(--recipients-accent-2))] h-full rounded-full"
                style={{
                  width: `${Math.min(100, (included.length / cap) * 100)}%`,
                }}
              />
            </div>
          </div>
          <div className="flex items-center justify-between gap-3">
            <WorkspaceCapacity />
            <Link
              href="/usage#allowances"
              className="inline-flex min-h-11 shrink-0 items-center text-xs text-link underline"
            >
              View allowances
            </Link>
          </div>
          <p className="text-xs leading-5 text-body">
            Each recipient gets a separate email from your Gmail.
          </p>
          <SendChecklist
            templateSelected={!!template}
            recipientCount={included.length}
            missingRoles={missingRoles.map((contact) => contact.name)}
            canEditRoles={access.features.recipientRoleOverride}
            attachResume={attachResume}
          />
          {!connected && (
            <p className="text-sm text-warning">
              Reconnect Gmail in{" "}
              <Link href="/settings" className="underline">
                Settings
              </Link>{" "}
              before sending.
            </p>
          )}
          <Feedback result={result} />
          <Button
            ref={sendButton}
            className="compose-send-button [font-family:var(--font-sans)] [background:var(--primary-action-gradient)] disabled:[background:var(--recipients-track,_var(--surface))] disabled:text-[var(--recipients-text-muted,_var(--muted-foreground))] disabled:shadow-none disabled:opacity-[1] w-full"
            disabled={
              busy ||
              !connected ||
              !readyToSend ||
              (displayedQuota.mode === "gated" &&
                !displayedQuota.sendingAllowed)
            }
            onClick={() => {
              if (!template || !included.length) {
                setResult({
                  ok: false,
                  message:
                    "Choose a template and at least one eligible recipient.",
                });
                return;
              }
              if (
                displayedQuota.used + included.length > displayedQuota.limit ||
                (displayedQuota.mode === "gated" &&
                  displayedQuota.monthly.remaining < included.length)
              ) {
                if (
                  displayedQuota.mode === "gated" &&
                  displayedQuota.plan === "FREE"
                ) {
                  setResult(undefined);
                  setExceededAllowances(
                    (["daily", "monthly"] as const)
                      .filter(
                        (period) =>
                          displayedQuota[period].remaining < included.length,
                      )
                      .map((period) => ({
                        label: period === "daily" ? "Daily" : "Monthly",
                        remaining: displayedQuota[period].remaining,
                        resetAt: displayedQuota[period].resetsAt,
                      })),
                  );
                  return;
                }
                setResult({
                  ok: false,
                  message:
                    displayedQuota.mode === "gated"
                      ? "This campaign would exceed your daily or monthly allowance. Check the remaining capacity and reset times."
                      : "This campaign would exceed your 24-hour limit.",
                });
                return;
              }
              if (included.some((c) => !getRole(c).trim())) {
                setResult({
                  ok: false,
                  message: "Choose a job role for every recipient.",
                });
                return;
              }
              const validation = templateSchema.safeParse(template);
              if (!validation.success) {
                setResult({
                  ok: false,
                  message: validation.error.issues[0].message,
                });
                return;
              }
              const key = idempotencyKey || crypto.randomUUID();
              setKey(key);
              start(async () => {
                const r = await submitCampaign({
                  templateId,
                  recipientIds: selected.map((c) => c.id),
                  recipientRoles: Object.fromEntries(
                    selected
                      .filter((c) => getRole(c).trim())
                      .map((c) => [c.id, getRole(c)]),
                  ),
                  attachResume,
                  resendIds,
                  idempotencyKey: key,
                });
                setResult(r);
                if (!r.ok) {
                  if (
                    r.code === "USAGE_CAPACITY_EXCEEDED" &&
                    displayedQuota.mode === "gated" &&
                    displayedQuota.plan === "FREE"
                  ) {
                    setResult(undefined);
                    setExceededAllowances([
                      {
                        label:
                          r.allowance === "DAILY"
                            ? "Daily"
                            : r.allowance === "MONTHLY"
                              ? "Monthly"
                              : "Sending",
                        remaining: r.remaining,
                        resetAt: r.resetAt,
                      },
                    ]);
                  }
                  refreshWorkspaceAccess();
                  router.refresh();
                }
                if (r.ok) {
                  sendingStatus?.markQueued();
                  setRecipientRoles({});
                  setSelected([]);
                  setKey("");
                  router.push(`/history?campaign=${r.id}`);
                }
              });
            }}
          >
            <Send aria-hidden="true" />
            {pending
              ? "Queuing…"
              : `Send to ${included.length} recipient${included.length === 1 ? "" : "s"}`}
          </Button>
        </section>
      </aside>
      {exceededAllowances && (
        <PremiumUpgradeDialog
          reason="allowance"
          allowanceScope={
            exceededAllowances.some(
              (allowance) => allowance.label === "Daily",
            ) &&
            exceededAllowances.some(
              (allowance) => allowance.label === "Monthly",
            )
              ? "both"
              : exceededAllowances[0]?.label === "Monthly"
                ? "monthly"
                : "daily"
          }
          premiumPrice={premiumPrice}
          returnFocusRef={sendButton}
          onClose={() => setExceededAllowances(null)}
        >
          <div className="mt-3 grid gap-3 rounded-2xl border border-upgrade-border bg-upgrade-surface px-4 py-3.5 text-sm min-[560px]:grid-cols-2">
            {exceededAllowances?.map(({ label, remaining, resetAt }) => (
              <section key={label} aria-label={`${label} sending allowance`}>
                <h3 className="text-xs font-semibold uppercase tracking-wide text-upgrade-muted">
                  {label} allowance
                </h3>
                <p className="mt-1 text-2xl font-bold leading-none">
                  {remaining ?? "—"}
                  <span className="ml-1.5 text-sm font-medium text-upgrade-muted">
                    remaining
                  </span>
                </p>
                <p className="mt-2 text-xs text-upgrade-muted">
                  Resets <DateTime value={resetAt ?? null} />
                </p>
              </section>
            ))}
          </div>
        </PremiumUpgradeDialog>
      )}
      <dialog
        ref={removalDialog}
        aria-labelledby="remove-shortlist-title"
        aria-describedby="remove-shortlist-description"
        onCancel={(event) => {
          if (removalInFlight.current) event.preventDefault();
        }}
        onClose={() => {
          if (removalSucceeded.current) shortlistSection.current?.focus();
          else removalTrigger.current?.focus();
        }}
      >
        <h2 id="remove-shortlist-title" className="text-xl font-semibold">
          Remove {removalContact?.name} from shortlist?
        </h2>
        <p
          id="remove-shortlist-description"
          className="mt-3 text-sm leading-6 text-body"
        >
          This person will be removed from your shortlist. Their contact and
          email history will be kept.
        </p>
        <div className="mt-6 flex justify-end gap-2">
          <Button
            type="button"
            variant="outline"
            autoFocus
            disabled={removing}
            onClick={() => {
              if (!removalInFlight.current) removalDialog.current?.close();
            }}
          >
            Cancel
          </Button>
          <Button
            type="button"
            variant="destructive"
            disabled={busy}
            onClick={confirmRemoval}
          >
            {removing ? "Removing…" : "Remove"}
          </Button>
        </div>
        {removalResult?.ok === false && <Feedback result={removalResult} />}
      </dialog>
    </div>
  );
}
